INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT '1ef12f5a-35b9-5678-afea-eea0ec8ddf1e' || ':' || json_extract(e.value,'$.ref'), '1ef12f5a-35b9-5678-afea-eea0ec8ddf1e', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = 'e73f724b-6aff-5fd5-a73a-572221e46ca6';
INSERT OR IGNORE INTO courses (id, slug, title, description, subject_id, age_band, status) VALUES ('f04b9d21-c217-5656-a9dc-3f37eaee1b1f', 'data-ai-class-4', 'Computer Science, Data & AI (Class 4)', 'Computer Science, Data & AI for Class 4', 'data-ai', '9-10', 'published');
INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('da7fa757-ac9b-5ff6-abbb-7e7135fe82c1', 'f04b9d21-c217-5656-a9dc-3f37eaee1b1f', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-data-ai-class-4","subject":"data-ai","title":"Computing, Data & AI Check-In: Where Am I?","summary":"Check what you know about algorithms, loops, decisions, data, and how AI learns so we can plan your coding and data year.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show I can read and fix simple algorithms","Show I can read and use data tables and charts","Show what I understand about how AI learns and staying safe online"],"tags":["diagnostic","week-1"],"curriculum":{"course":"data-ai-class-4","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Digital Explorer!"},{"type":"text","markdown":"This is a **check-in** to see what you already know about computing, data and AI. No computer is needed, just your brain and a pencil."},{"type":"image","emoji":"💻","alt":"Code, data and AI","caption":"Code, data and AI"},{"type":"heading","text":"Stop 1: Algorithms and loops"},{"type":"text","markdown":"An **algorithm** is a precise list of steps. A **loop** repeats steps so you do not have to write them again: repeat 4 times (move forward, turn right) draws a square. **Debugging** means finding and fixing mistakes."},{"type":"check","question":{"type":"number","prompt":"A robot does this 3 times: move 2 steps forward. How many steps does it move in total?","answer":{"value":6,"tolerance":0}}},{"type":"explainer","title":"A loop draws a square","scenes":[{"caption":"A robot starts in the corner. The loop says: move forward, turn right.","items":[{"emoji":"🤖","x":20,"y":25,"id":"r","size":3,"label":"start"}]},{"caption":"Forward and turn right. That was one time round the loop.","items":[{"emoji":"🤖","x":75,"y":25,"id":"r","size":3,"label":"1"}]},{"caption":"Repeat! Forward and turn right again.","items":[{"emoji":"🤖","x":75,"y":75,"id":"r","size":3,"label":"2"}]},{"caption":"And again. Three times so far.","items":[{"emoji":"🤖","x":20,"y":75,"id":"r","size":3,"label":"3"}]},{"caption":"Repeat 4 times and the robot is back at the start, having drawn a square. One loop saved lots of writing!","items":[{"emoji":"🤖","x":20,"y":25,"id":"r","size":3,"label":"4","anim":"bounce"}]}]},{"type":"heading","text":"Stop 2: Decisions"},{"type":"text","markdown":"Programs make choices with **if** statements: **if** it is raining, **then** take an umbrella, **else** wear sunglasses."},{"type":"check","question":{"type":"multiple_choice","prompt":"If it is raining take an umbrella, else wear sunglasses. It is sunny. What do you take?","options":[{"id":"a","text":"Umbrella"},{"id":"b","text":"Sunglasses"}],"answer":["b"]}},{"type":"activity","title":"Debug the sandwich","materials":["paper","pencil"],"instructions":["Write a 6 step algorithm for making a sandwich.","Swap with a grown-up who follows it exactly like a robot.","Find any step that was unclear and fix (debug) it."]},{"type":"heading","text":"Stop 3: Data"},{"type":"text","markdown":"**Data** is facts we collect. We store it in **tables** (rows and columns) and show it in **charts**. A **bar chart** makes comparing categories easy. Always check the labels and the scale."},{"type":"chart","kind":"table","title":"A table: our favourite sports","caption":"A table stores data in rows and columns.","rows":[{"label":"Cricket","value":8},{"label":"Football","value":12},{"label":"Swimming","value":5}]},{"type":"chart","kind":"bar_chart","title":"A bar chart of the same data","caption":"The taller the bar, the more votes. Football is the tallest.","rows":[{"label":"Cricket","value":8},{"label":"Football","value":12},{"label":"Swimming","value":5}]},{"type":"check","question":{"type":"multiple_choice","prompt":"A bar chart shows Cricket 8, Football 12, Swimming 5 votes. Which is most popular?","options":[{"id":"a","text":"Cricket"},{"id":"b","text":"Football"},{"id":"c","text":"Swimming"}],"answer":["b"]}},{"type":"heading","text":"Stop 4: How AI learns"},{"type":"text","markdown":"Some programs do not follow fixed rules. Instead they learn from many **examples**, called **training data**. If you show a computer thousands of cat and dog pictures, it learns to tell them apart. If the examples are unfair or missing, the AI can make **mistakes**, so people must check its answers."},{"type":"check","question":{"type":"true_false","prompt":"An AI learns by looking at lots of examples.","answer":[true]}},{"type":"heading","text":"Stop 5: Safe and kind online"},{"type":"text","markdown":"A **strong password** is long and mixes words, numbers and symbols. Never share it. Think before you click or post, and tell a trusted adult if something feels wrong."},{"type":"reveal","prompt":"Why might an AI that only saw pictures of golden retrievers get confused by a poodle?","answer_markdown":"Because it learned from a narrow set of examples. Good training data needs variety."},{"type":"brain_game","game":"remember_order","title":"Copy the sequence","goal":"Computers follow steps in order. Watch, then copy the order.","emojis":["🟥","🟨","🟩","🟦"]},{"type":"summary","points":["Algorithms are exact steps and loops repeat them.","If / else lets programs make decisions.","Tables and charts help us understand data.","AI learns from examples and can make mistakes.","Strong, secret passwords keep us safe."]},{"type":"callout","style":"tip","markdown":"Ready? Start the quiz. 12 questions, about 15 minutes. Do your best!"},{"type":"glossary","terms":[{"term":"algorithm","meaning":"A precise list of steps to solve a problem."},{"term":"loop","meaning":"Steps that repeat so you do not have to write them again."},{"term":"debugging","meaning":"Finding and fixing mistakes in a program."},{"term":"bar chart","meaning":"A graph that uses bars to compare amounts."},{"term":"training data","meaning":"The examples an AI learns from."},{"term":"strong password","meaning":"A long mix of letters, numbers and symbols that is hard to guess."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"type":"order","prompt":"Put the steps for making toast in a sensible order.","ref":"q1","skill_tag":"algorithms.order","points":2,"items":[{"id":"a","text":"Put bread in the toaster"},{"id":"b","text":"Press the lever down"},{"id":"c","text":"Wait for it to pop up"},{"id":"d","text":"Spread butter"}],"answer":["a","b","c","d"]},{"type":"number","prompt":"Repeat 5 times: clap twice. How many claps in total?","ref":"q2","skill_tag":"loops.count","answer":{"value":10,"tolerance":0}},{"type":"multiple_choice","prompt":"What does a loop do in a program?","ref":"q3","skill_tag":"loops.meaning","options":[{"id":"a","text":"Repeats instructions"},{"id":"b","text":"Stops the computer"},{"id":"c","text":"Draws a circle only"}],"answer":["a"]},{"type":"multiple_choice","prompt":"IF the number is bigger than 10 say BIG, ELSE say SMALL. The number is 7. What does the program say?","ref":"q4","skill_tag":"conditionals.if_else","options":[{"id":"a","text":"BIG"},{"id":"b","text":"SMALL"},{"id":"c","text":"Nothing"}],"answer":["b"]},{"type":"multiple_choice","prompt":"A robot should draw a square: forward, turn, forward, turn, forward, turn, forward. It draws a triangle-like shape. What bug is most likely?","ref":"q5","skill_tag":"debugging.find","points":2,"options":[{"id":"a","text":"A missing step or wrong turn count"},{"id":"b","text":"The robot is too heavy"},{"id":"c","text":"The paper is blue"}],"answer":["a"]},{"type":"multiple_choice","prompt":"In a table: Mon 3 cars, Tue 7 cars, Wed 5 cars. On which day were there most cars?","ref":"q6","skill_tag":"data.read_table","options":[{"id":"a","text":"Mon"},{"id":"b","text":"Tue"},{"id":"c","text":"Wed"}],"answer":["b"]},{"type":"number","prompt":"Using that table (3, 7 and 5 cars), how many cars were counted in total?","ref":"q7","skill_tag":"data.calculate","points":2,"answer":{"value":15,"tolerance":0}},{"type":"multiple_choice","prompt":"Which chart is best for comparing how many students like each fruit?","ref":"q8","skill_tag":"data.chart_type","options":[{"id":"a","text":"Bar chart"},{"id":"b","text":"A photo"},{"id":"c","text":"A map"}],"answer":["a"]},{"type":"multiple_choice","prompt":"What does an AI need to learn to recognise cats?","ref":"q9","skill_tag":"ai.training","options":[{"id":"a","text":"Lots of cat examples"},{"id":"b","text":"A cat as a pet"},{"id":"c","text":"Nothing at all"}],"answer":["a"]},{"type":"true_false","prompt":"An AI answer is always right, so we never need to check it.","explanation":"AI can make mistakes, so people should check.","ref":"q10","skill_tag":"ai.limits","answer":[false]},{"type":"multiple_choice","prompt":"Which is the strongest password?","ref":"q11","skill_tag":"safety.password","options":[{"id":"a","text":"password"},{"id":"b","text":"football1"},{"id":"c","text":"R7!blue-kite-42"}],"answer":["c"]},{"type":"multiple_choice","prompt":"A stranger online asks where you live. What should you do?","ref":"q12","skill_tag":"safety.online","options":[{"id":"a","text":"Tell them"},{"id":"b","text":"Do not answer and tell a trusted adult"},{"id":"c","text":"Ask them for their address first"}],"answer":["b"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'ab3c1737-38be-5d2c-a43e-15f7722e2276', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 2, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
