INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('10a07364-5786-5b8c-adf1-7f482a2bff8d', '736a0b85-b107-5f53-ab88-cda06a05f74b', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-english-class-4","subject":"english","title":"English Check-In: Where Am I?","summary":"Check what you know about word classes, punctuation, tenses, word building, vocabulary and reading between the lines so we can plan your English year.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show I can name nouns, verbs, adjectives and adverbs","Show I can use capital letters, commas, apostrophes and speech marks","Show I can use tenses, prefixes and word meanings, and read between the lines"],"tags":["diagnostic","week-1"],"curriculum":{"course":"english-class-4","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Wordsmith!"},{"type":"text","markdown":"This is a **check-in**, not a test. Good writers are curious about words and not afraid to guess. Show us what you know and where you want to learn more."},{"type":"image","emoji":"✍️","alt":"A hand writing","caption":"Time to play with words!"},{"type":"heading","text":"Stop 1: The jobs words do"},{"type":"text","markdown":"Every word has a job. A **noun** names a person, place or thing. A **verb** is an action. An **adjective** describes a noun. An **adverb** tells us how, when or where something happens."},{"type":"explainer","title":"The jobs in a sentence","scenes":[{"caption":"Here is a sentence: The big dog runs quickly.","items":[{"emoji":"The","x":8,"y":50},{"emoji":"big","x":27,"y":50,"id":"adj"},{"emoji":"dog","x":46,"y":50,"id":"noun"},{"emoji":"runs","x":65,"y":50,"id":"verb"},{"emoji":"quickly","x":87,"y":50,"id":"adv"}]},{"caption":"Dog is a noun. It names the animal.","items":[{"emoji":"The","x":8,"y":50},{"emoji":"big","x":27,"y":50,"id":"adj"},{"emoji":"dog","x":46,"y":50,"id":"noun","anim":"pulse","label":"noun"},{"emoji":"runs","x":65,"y":50,"id":"verb"},{"emoji":"quickly","x":87,"y":50,"id":"adv"}]},{"caption":"Runs is a verb. It is the action.","items":[{"emoji":"The","x":8,"y":50},{"emoji":"big","x":27,"y":50,"id":"adj"},{"emoji":"dog","x":46,"y":50,"id":"noun","label":"noun"},{"emoji":"runs","x":65,"y":50,"id":"verb","anim":"pulse","label":"verb"},{"emoji":"quickly","x":87,"y":50,"id":"adv"}]},{"caption":"Big is an adjective. It describes the dog.","items":[{"emoji":"The","x":8,"y":50},{"emoji":"big","x":27,"y":50,"id":"adj","anim":"pulse","label":"adjective"},{"emoji":"dog","x":46,"y":50,"id":"noun","label":"noun"},{"emoji":"runs","x":65,"y":50,"id":"verb","label":"verb"},{"emoji":"quickly","x":87,"y":50,"id":"adv"}]},{"caption":"Quickly is an adverb. It tells us how the dog runs.","items":[{"emoji":"The","x":8,"y":50},{"emoji":"big","x":27,"y":50,"id":"adj","label":"adjective"},{"emoji":"dog","x":46,"y":50,"id":"noun","label":"noun"},{"emoji":"runs","x":65,"y":50,"id":"verb","label":"verb"},{"emoji":"quickly","x":87,"y":50,"id":"adv","anim":"pulse","label":"adverb"},{"emoji":"🐕","x":50,"y":15,"size":3,"anim":"bounce"}]}]},{"type":"check","question":{"type":"multi_select","prompt":"Pick both verbs: The children laughed and played.","options":[{"id":"a","text":"children"},{"id":"b","text":"laughed"},{"id":"c","text":"and"},{"id":"d","text":"played"}],"answer":["b","d"]}},{"type":"heading","text":"Stop 2: Punctuation"},{"type":"text","markdown":"**Capital letters** begin sentences and names. A **comma** separates the things in a list. **Speech marks** go round the exact words someone says. An **apostrophe** shows that letters are missing, or that something belongs to someone."},{"type":"explainer","title":"What the apostrophe does","scenes":[{"caption":"Two words: do and not.","items":[{"emoji":"do","x":30,"y":50,"id":"a","size":3},{"emoji":"not","x":65,"y":50,"id":"b","size":3}]},{"caption":"Squash them together and the letter o falls out.","items":[{"emoji":"do","x":40,"y":50,"id":"a","size":3},{"emoji":"n''t","x":62,"y":50,"id":"b","size":3,"anim":"pulse"}]},{"caption":"The apostrophe takes the place of the missing o: don''t.","items":[{"emoji":"don''t","x":50,"y":50,"id":"a","size":3,"anim":"grow","label":"apostrophe replaces o"}]},{"caption":"It also shows who owns something. The dog''s bone is the bone that belongs to the dog.","items":[{"emoji":"🐕","x":30,"y":50,"size":3,"label":"dog''s"},{"emoji":"🦴","x":70,"y":55,"size":3,"anim":"bounce","label":"bone"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which sentence uses an apostrophe correctly?","ref":"c1","skill_tag":"punctuation.apostrophe","options":[{"id":"a","text":"The dogs bone is big."},{"id":"b","text":"The dog''s bone is big."},{"id":"c","text":"The dogs'' bone''s is big."}],"answer":["b"]}},{"type":"check","question":{"type":"true_false","prompt":"A comma can be used to separate the things in a list.","ref":"c2","skill_tag":"punctuation.comma","answer":[true]}},{"type":"heading","text":"Stop 3: Tenses"},{"type":"text","markdown":"**Tense** tells us when something happens. Past: I walked. Present: I walk. Future: I will walk. Some verbs change in tricky ways, like go becomes went."},{"type":"explainer","title":"Past, present and future","scenes":[{"caption":"Yesterday I walked to school. That is the past.","items":[{"emoji":"🚶","x":20,"y":55,"id":"me","size":3,"label":"walked (past)"},{"emoji":"🏫","x":85,"y":40,"size":3}]},{"caption":"Today I walk to school. That is the present.","items":[{"emoji":"🚶","x":50,"y":55,"id":"me","size":3,"anim":"bounce","label":"walk (present)"},{"emoji":"🏫","x":85,"y":40,"size":3}]},{"caption":"Tomorrow I will walk to school. That is the future.","items":[{"emoji":"🚶","x":78,"y":55,"id":"me","size":3,"label":"will walk (future)"},{"emoji":"🏫","x":85,"y":40,"size":3}]}]},{"type":"check","question":{"type":"match","prompt":"Match each verb to its past tense.","ref":"c3","skill_tag":"grammar.tense","left":[{"id":"l1","text":"run"},{"id":"l2","text":"eat"},{"id":"l3","text":"swim"}],"right":[{"id":"r1","text":"ran"},{"id":"r2","text":"ate"},{"id":"r3","text":"swam"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}}},{"type":"heading","text":"Stop 4: Building words and meanings"},{"type":"text","markdown":"A **prefix** goes at the start of a word and changes its meaning, like un in unhappy. A **suffix** goes at the end, like ful in careful."},{"type":"explainer","title":"Building new words","scenes":[{"caption":"Start with the word happy.","items":[{"emoji":"happy","x":55,"y":50,"id":"w","size":3}]},{"caption":"Add the prefix un at the start.","items":[{"emoji":"un","x":25,"y":50,"id":"p","size":3,"anim":"grow"},{"emoji":"happy","x":62,"y":50,"id":"w","size":3}]},{"caption":"Unhappy means not happy. A prefix changed the meaning!","items":[{"emoji":"unhappy","x":50,"y":50,"id":"w","size":3,"anim":"pulse","label":"not happy"},{"emoji":"😢","x":50,"y":15,"size":3}]},{"caption":"Now try a suffix. Add ful to care and you get careful, which means full of care.","items":[{"emoji":"care","x":35,"y":50,"id":"c","size":3},{"emoji":"ful","x":68,"y":50,"id":"s","size":3,"anim":"grow","label":"suffix"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which prefix makes happy mean not happy?","ref":"c4","skill_tag":"morphology.prefix","options":[{"id":"a","text":"un"},{"id":"b","text":"re"},{"id":"c","text":"pre"}],"answer":["a"]}},{"type":"text","markdown":"A **synonym** is a word with almost the same meaning. An **antonym** is a word with the opposite meaning."},{"type":"explainer","title":"Synonyms and antonyms","scenes":[{"caption":"Big and large mean almost the same. They are synonyms.","items":[{"emoji":"🐘","x":30,"y":50,"id":"e1","size":3,"label":"big"},{"emoji":"🐘","x":70,"y":50,"id":"e2","size":3,"label":"large"}]},{"caption":"Big and small mean the opposite. They are antonyms.","items":[{"emoji":"🐘","x":30,"y":50,"id":"e1","size":3,"label":"big"},{"emoji":"🐭","x":70,"y":60,"id":"m1","size":1,"label":"small"}]}]},{"type":"check","question":{"type":"multiple_choice","prompt":"Which word is a synonym of tiny?","ref":"c5","skill_tag":"vocabulary.synonyms","options":[{"id":"a","text":"small"},{"id":"b","text":"huge"},{"id":"c","text":"loud"}],"answer":["a"]}},{"type":"heading","text":"Stop 5: Reading between the lines"},{"type":"text","markdown":"Good readers notice clues. Read this: Mia packed her bag the night before the trip. In the morning she woke early and ran to the window. Thick grey clouds covered the sky, but she grinned and pulled on her raincoat anyway. She could not wait to see the waterfalls."},{"type":"image","emoji":"🌧️","alt":"Grey rainy clouds","caption":"Grey clouds over Mia''s trip"},{"type":"check","question":{"type":"multiple_choice","prompt":"How did Mia feel about the trip?","ref":"c6","skill_tag":"reading.inference","options":[{"id":"a","text":"excited"},{"id":"b","text":"bored"},{"id":"c","text":"afraid"}],"answer":["a"]}},{"type":"reveal","prompt":"Which clues in the story tell you how Mia felt?","answer_markdown":"She packed the night before, woke early, ran to the window and grinned even though it was cloudy. All of these clues show she was excited."},{"type":"activity","title":"Sentence builder","materials":["paper","a pencil"],"instructions":["Write one sentence that has a noun, a verb, an adjective and an adverb in it.","Underline each of the four words and write its job above it.","Now change the sentence into the past tense and read it aloud."]},{"type":"brain_game","game":"remember_order","title":"Writer''s memory","goal":"Watch the order, then copy it.","emojis":["📖","✏️","🔤","📝"]},{"type":"summary","points":["Nouns name, verbs act, adjectives describe and adverbs tell how.","Punctuation marks help the reader: capital letters, commas, apostrophes and speech marks.","Tense tells us if something happened in the past, present or future.","Prefixes and suffixes change words. Synonyms and antonyms are about meaning.","Clues in a text help us work out what is not said."]},{"type":"callout","style":"tip","markdown":"Ready? Start the quiz. It has 12 questions and takes about 15 minutes. A guess is better than a blank."},{"type":"glossary","terms":[{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"noun","meaning":"A word that names a person, place or thing."},{"term":"verb","meaning":"A word for an action or a state, like run or is."},{"term":"adjective","meaning":"A word that describes a noun, like big or red."},{"term":"adverb","meaning":"A word that tells how, when or where something happens, like quickly."},{"term":"capital letters","meaning":"Big letters used at the start of sentences and names."},{"term":"comma","meaning":"A small mark (,) that separates things in a list or pauses a sentence."},{"term":"speech marks","meaning":"Marks (\" \") that go around the exact words someone says."},{"term":"apostrophe","meaning":"A mark ('') that shows missing letters, as in don''t, or belonging, as in the dog''s bone."},{"term":"tense","meaning":"Tells us when something happens: past, present or future."},{"term":"prefix","meaning":"A group of letters added to the start of a word to change its meaning."},{"term":"suffix","meaning":"A group of letters added to the end of a word to change its meaning."},{"term":"synonym","meaning":"A word that means almost the same as another word."},{"term":"antonym","meaning":"A word that means the opposite of another word."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"type":"multiple_choice","prompt":"Which word is a noun? A quiet librarian smiled.","ref":"q1","skill_tag":"grammar.nouns","options":[{"id":"a","text":"quiet"},{"id":"b","text":"librarian"},{"id":"c","text":"smiled"}],"answer":["b"],"hint":"A noun names a person, place or thing.","explanation":"Librarian names a person. Quiet describes and smiled is an action."},{"type":"multiple_choice","prompt":"Which word is an adjective? The enormous whale swam away.","ref":"q2","skill_tag":"grammar.adjectives","options":[{"id":"a","text":"enormous"},{"id":"b","text":"whale"},{"id":"c","text":"swam"},{"id":"d","text":"away"}],"answer":["a"],"hint":"It describes the whale.","explanation":"Enormous describes the whale, so it is an adjective."},{"type":"multiple_choice","prompt":"Which word is the adverb? Birds sing sweetly.","ref":"q3","skill_tag":"grammar.adverbs","options":[{"id":"a","text":"Birds"},{"id":"b","text":"sing"},{"id":"c","text":"sweetly"}],"answer":["c"],"hint":"It tells us how the birds sing.","explanation":"Sweetly tells us how the birds sing, so it is an adverb."},{"type":"multi_select","prompt":"Pick the two verbs: We painted pictures and hung them up.","ref":"q4","skill_tag":"grammar.verbs","options":[{"id":"a","text":"painted"},{"id":"b","text":"pictures"},{"id":"c","text":"hung"},{"id":"d","text":"them"}],"answer":["a","c"],"points":2,"hint":"Look for the two actions.","explanation":"Painted and hung are the actions, so they are verbs."},{"type":"multiple_choice","prompt":"Which sentence is correct?","ref":"q5","skill_tag":"punctuation.apostrophe","options":[{"id":"a","text":"I cant find Toms bag."},{"id":"b","text":"I can''t find Tom''s bag."},{"id":"c","text":"I ca''nt find Toms'' bag."}],"answer":["b"],"points":2,"hint":"One apostrophe shows a missing letter. One shows who owns the bag.","explanation":"Can''t has a missing o and Tom''s bag belongs to Tom."},{"type":"multiple_choice","prompt":"Which sentence uses speech marks correctly?","ref":"q6","skill_tag":"punctuation.speech_marks","options":[{"id":"a","text":"She asked, Can I come?"},{"id":"b","text":"She asked, \"Can I come?\""},{"id":"c","text":"She \"asked, Can\" I come?"}],"answer":["b"],"hint":"Speech marks go round the exact words spoken.","explanation":"The spoken words, Can I come?, sit inside the speech marks."},{"type":"match","prompt":"Match each verb to its past tense.","ref":"q7","skill_tag":"grammar.tense","left":[{"id":"l1","text":"go"},{"id":"l2","text":"see"},{"id":"l3","text":"buy"}],"right":[{"id":"r1","text":"went"},{"id":"r2","text":"saw"},{"id":"r3","text":"bought"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"},"points":2,"hint":"Say each one in a sentence that starts with yesterday.","explanation":"Go becomes went, see becomes saw and buy becomes bought."},{"type":"short_text","prompt":"Write the plural of child.","ref":"q8","skill_tag":"spelling.plurals","answer":{"accepted":["children"]},"hint":"It does not end in s.","explanation":"The plural of child is children."},{"type":"multiple_choice","prompt":"Which sentence is in the future tense?","ref":"q9","skill_tag":"grammar.tense","options":[{"id":"a","text":"I walked to school."},{"id":"b","text":"I walk to school."},{"id":"c","text":"I will walk to school."}],"answer":["c"],"hint":"Look for the word that says it has not happened yet.","explanation":"Will walk tells us it is going to happen."},{"type":"multiple_choice","prompt":"Which word means to build again?","ref":"q10","skill_tag":"morphology.prefix","options":[{"id":"a","text":"rebuild"},{"id":"b","text":"unbuild"},{"id":"c","text":"prebuild"}],"answer":["a"],"hint":"Which prefix means again?","explanation":"The prefix re means again, so rebuild is to build again."},{"type":"multiple_choice","prompt":"Which word is an antonym of ancient?","ref":"q11","skill_tag":"vocabulary.antonyms","options":[{"id":"a","text":"modern"},{"id":"b","text":"old"},{"id":"c","text":"huge"}],"answer":["a"],"hint":"An antonym means the opposite. Ancient means very, very old.","explanation":"Modern means new, which is the opposite of ancient."},{"type":"multiple_choice","prompt":"The cake was gone from the plate. Tom''s sister had chocolate on her chin and a guilty smile. What can we guess?","ref":"q12","skill_tag":"reading.inference","options":[{"id":"a","text":"His sister ate the cake"},{"id":"b","text":"Tom lost the plate"},{"id":"c","text":"The cake was never made"}],"answer":["a"],"points":2,"hint":"Use the clues about the sister.","explanation":"The chocolate on her chin and her guilty smile are clues that she ate the cake."}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'a31c10a8-4f02-5604-a44f-01fa167a9776', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 4, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
