INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT 'ade7c0fa-48c9-5a45-a257-1769bce20753' || ':' || json_extract(e.value,'$.ref'), 'ade7c0fa-48c9-5a45-a257-1769bce20753', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = 'a158e9dc-1766-50e5-a116-4bc09a41ed23';
INSERT OR IGNORE INTO courses (id, slug, title, description, subject_id, age_band, status) VALUES ('a00278f6-1838-5725-a7dd-711f28f56169', 'maths-class-1', 'Maths (Class 1)', 'Maths for Class 1', 'maths', '7-8', 'published');
INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('6ed16360-df3c-5174-acbb-7ab926443ed0', 'a00278f6-1838-5725-a7dd-711f28f56169', '4aaa1400-fcb5-5271-a59a-3cff7d2e0778', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-maths-class-1","subject":"maths","title":"Maths Check-In: Where Am I?","summary":"A friendly tour of counting, adding, taking away, shapes and patterns, so we can see what you already know.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about counting and place value","Show what I can do with adding and taking away","Show what I know about shapes, patterns and measuring"],"tags":["diagnostic","week-1"],"curriculum":{"course":"maths-class-1","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Maths Explorer!"},{"type":"text","markdown":"This is a **check-in**, not a test. There are no wrong answers in the lesson, only chances to show what you already know. Take your time, use your fingers or draw if it helps, and ask a grown-up if you get stuck.\n\nToday we will visit five maths places: counting, adding, taking away, shapes and patterns."},{"type":"image","emoji":"🧮","alt":"Let''s explore maths!","caption":"Let''s explore maths!"},{"type":"heading","text":"Stop 1: Counting and numbers"},{"type":"text","markdown":"Numbers are like a ladder. Each step up is **one more**. Counting in 2s, 5s and 10s helps us count big groups quickly."},{"type":"chart","kind":"number_line","title":"Each step up is one more","caption":"3 is on the line. One more than 3 is 4.","from":0,"to":10,"marks":[3,4]},{"type":"check","question":{"type":"number","prompt":"Count by 2s: 2, 4, 6, 8, ... what comes next?","hint":"Add 2 to 8.","answer":{"value":10,"tolerance":0}}},{"type":"check","question":{"type":"multiple_choice","prompt":"Which number is the biggest?","hint":"Look at the tens first.","options":[{"id":"a","text":"19"},{"id":"b","text":"91"},{"id":"c","text":"29"}],"answer":["b"]}},{"type":"vocab","word":"tens and ones","meaning":"In the number 47, the 4 means 4 tens (40) and the 7 means 7 ones.","example":"47 = 40 + 7"},{"type":"heading","text":"Stop 2: Adding"},{"type":"text","markdown":"**Adding** means putting groups together. 3 apples and 2 apples make 5 apples. You can count on from the bigger number: for 6 + 3, start at 6 and count 7, 8, 9."},{"type":"check","question":{"type":"number","prompt":"What is 6 + 3?","answer":{"value":9,"tolerance":0}}},{"type":"check","question":{"type":"number","prompt":"What is 10 + 7?","answer":{"value":17,"tolerance":0}}},{"type":"activity","title":"Counting treasure","materials":["10 small things such as coins, buttons or pasta"],"instructions":["Put the things in a pile and count them.","Split them into two groups. How many in each?","Say the adding sentence, for example 4 + 6 = 10.","Try a different split and say the new sum."]},{"type":"explainer","title":"Apples and more apples","scenes":[{"caption":"You have 3 apples.","items":[{"emoji":"🍎","x":20,"y":50,"id":"a1","size":3},{"emoji":"🍎","x":35,"y":50,"id":"a2","size":3},{"emoji":"🍎","x":50,"y":50,"id":"a3","size":3}]},{"caption":"A friend gives you 2 more apples.","items":[{"emoji":"🍎","x":20,"y":50,"id":"a1","size":3},{"emoji":"🍎","x":35,"y":50,"id":"a2","size":3},{"emoji":"🍎","x":50,"y":50,"id":"a3","size":3},{"emoji":"🍎","x":70,"y":50,"id":"a4","size":3,"anim":"grow"},{"emoji":"🍎","x":85,"y":50,"id":"a5","size":3,"anim":"grow"}]},{"caption":"Count them all together: 3 and 2 make 5 apples!","items":[{"emoji":"🍎","x":20,"y":55,"id":"a1","size":3,"anim":"bounce"},{"emoji":"🍎","x":35,"y":55,"id":"a2","size":3,"anim":"bounce"},{"emoji":"🍎","x":50,"y":55,"id":"a3","size":3,"anim":"bounce"},{"emoji":"🍎","x":65,"y":55,"id":"a4","size":3,"anim":"bounce"},{"emoji":"🍎","x":80,"y":55,"id":"a5","size":3,"anim":"bounce"},{"emoji":"5","x":50,"y":15,"label":"3 + 2 = 5","size":3,"anim":"pulse"}]}]},{"type":"manipulative","title":"Split the treasure","goal":"Split the 10 coins between your two hands. How many can you put in each? Try a different split!","emoji":"🪙","count":10,"zones":["Left hand","Right hand"]},{"type":"heading","text":"Stop 3: Taking away"},{"type":"text","markdown":"**Taking away** (subtracting) means some things go away. You had 8 sweets and ate 3. Count back 3 from 8: 7, 6, 5. You have 5 left."},{"type":"chart","kind":"number_line","title":"Taking away 3 from 8","caption":"Start at 8 and hop back 3 steps. You land on 5.","from":0,"to":10,"marks":[8,5]},{"type":"check","question":{"type":"number","prompt":"What is 9 - 4?","answer":{"value":5,"tolerance":0}}},{"type":"check","question":{"type":"true_false","prompt":"If you have 5 pencils and add 0 more, you still have 5.","answer":[true]}},{"type":"heading","text":"Stop 4: Shapes and measuring"},{"type":"text","markdown":"A **triangle** has 3 sides. A **square** has 4 equal sides. A **circle** has no corners at all. We measure how long things are with a ruler, and tell the time with a clock."},{"type":"check","question":{"type":"multiple_choice","prompt":"How many sides does a triangle have?","options":[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"}],"answer":["b"]}},{"type":"heading","text":"Stop 5: Patterns"},{"type":"text","markdown":"A pattern repeats. Red, blue, red, blue, red, ... the next one is blue!"},{"type":"check","question":{"type":"multiple_choice","prompt":"What comes next? 🔴 🔵 🔵 🔴 🔵 🔵 🔴 ...","hint":"The pattern is red, blue, blue.","options":[{"id":"a","text":"🔴"},{"id":"b","text":"🔵"},{"id":"c","text":"🟢"}],"answer":["b"]}},{"type":"reveal","prompt":"Can you make up your own pattern with 3 different colours or shapes?","answer_markdown":"Any repeating group works. For example: star, heart, moon, star, heart, moon!"},{"type":"brain_game","game":"memory_match","title":"Find the matching pairs","goal":"Turn over two cards. Can you find all the pairs?","emojis":["1️⃣","2️⃣","3️⃣","🔺","🟦","⭕"]},{"type":"summary","points":["Counting in 2s, 5s and 10s is quick.","Adding puts groups together and taking away makes a group smaller.","Shapes have a fixed number of sides.","A pattern repeats, so you can guess what comes next."]},{"type":"callout","style":"tip","markdown":"When you are ready, start the quiz. It has 12 questions and takes about 15 minutes. Do your best. Everything you show us helps plan your next lessons!"},{"type":"glossary","terms":[{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"adding","meaning":"Putting groups together to find how many there are altogether."},{"term":"taking away","meaning":"Some things go away, so you count what is left."},{"term":"triangle","meaning":"A shape with 3 sides and 3 corners."},{"term":"square","meaning":"A shape with 4 equal sides and 4 corners."},{"term":"circle","meaning":"A round shape with no corners."},{"term":"pattern","meaning":"Something that repeats again and again, like red, blue, red, blue."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"type":"multiple_choice","prompt":"How many stars? ⭐⭐⭐⭐⭐⭐⭐","emoji":"⭐","ref":"q1","skill_tag":"number.count","options":[{"id":"a","text":"6"},{"id":"b","text":"7"},{"id":"c","text":"8"},{"id":"d","text":"9"}],"answer":["b"]},{"type":"number","prompt":"Count by 5s: 5, 10, 15, ... what comes next?","ref":"q2","skill_tag":"number.skip_count","answer":{"value":20,"tolerance":0}},{"type":"multiple_choice","prompt":"Which number is the smallest?","ref":"q3","skill_tag":"number.compare","options":[{"id":"a","text":"34"},{"id":"b","text":"43"},{"id":"c","text":"24"},{"id":"d","text":"42"}],"answer":["c"]},{"type":"number","prompt":"In the number 36, how many tens are there?","hint":"36 = 30 + 6","ref":"q4","skill_tag":"number.place_value","answer":{"value":3,"tolerance":0}},{"type":"number","prompt":"What is 8 + 7?","ref":"q5","skill_tag":"add.within_20","answer":{"value":15,"tolerance":0}},{"type":"number","prompt":"What is 12 + 5?","ref":"q6","skill_tag":"add.within_20","answer":{"value":17,"tolerance":0}},{"type":"number","prompt":"What is 15 - 6?","ref":"q7","skill_tag":"subtract.within_20","answer":{"value":9,"tolerance":0}},{"type":"number","prompt":"Sam has 14 marbles. He gives 5 to his sister. How many marbles does Sam have now?","ref":"q8","skill_tag":"word_problem","points":2,"answer":{"value":9,"tolerance":0}},{"type":"multiple_choice","prompt":"Which shape has 4 equal sides?","ref":"q9","skill_tag":"shape.properties","options":[{"id":"a","text":"Triangle"},{"id":"b","text":"Circle"},{"id":"c","text":"Square"},{"id":"d","text":"Rectangle with 2 long sides"}],"answer":["c"]},{"type":"multiple_choice","prompt":"The short hand points to 3 and the long hand points to 12. What time is it?","hint":"The long hand on 12 means o''clock.","ref":"q10","skill_tag":"time.hours","options":[{"id":"a","text":"12 o''clock"},{"id":"b","text":"3 o''clock"},{"id":"c","text":"6 o''clock"}],"answer":["b"]},{"type":"multiple_choice","prompt":"What comes next? 2, 4, 6, 8, ...","ref":"q11","skill_tag":"pattern.next","options":[{"id":"a","text":"9"},{"id":"b","text":"10"},{"id":"c","text":"12"}],"answer":["b"]},{"type":"number","prompt":"There are 3 bags with 2 apples in each bag. How many apples are there altogether?","hint":"Add 2 + 2 + 2.","ref":"q12","skill_tag":"word_problem","points":2,"answer":{"value":6,"tolerance":0}}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT '5c30cbe4-34cb-5d30-a52e-e6471efcd9a3', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 7, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
INSERT OR IGNORE INTO course_lessons (course_id, lesson_id, position, semester, week) VALUES ('a00278f6-1838-5725-a7dd-711f28f56169', '5c30cbe4-34cb-5d30-a52e-e6471efcd9a3', 101, 1, 1);
INSERT OR IGNORE INTO quizzes (id, kind, lesson_id, version, is_current, pass_percent, shuffle_questions, shuffle_options, max_attempts) VALUES ('a7bf6d15-d3a4-5f89-a8f3-df8aba244bb1', 'lesson', '5c30cbe4-34cb-5d30-a52e-e6471efcd9a3', 1, 1, 1, 0, 1, NULL);
INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT 'a7bf6d15-d3a4-5f89-a8f3-df8aba244bb1' || ':' || json_extract(e.value,'$.ref'), 'a7bf6d15-d3a4-5f89-a8f3-df8aba244bb1', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = '5c30cbe4-34cb-5d30-a52e-e6471efcd9a3';
