INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('843afdf2-7892-53a2-a60c-8a6caa92ee2f', '6d15385c-169b-5165-a4a6-56a7555dbc1a', '4aaa1400-fcb5-5271-a59a-3cff7d2e0778', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-science-class-1","subject":"science","title":"Science Check-In: Where Am I?","summary":"Explore living things, plants, materials, weather and forces so we can see what you already know about the world.","age_band":"7-8","difficulty":1,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about living things and plants","Show what I know about materials and weather","Show what I know about pushes and pulls"],"tags":["diagnostic","week-1"],"curriculum":{"course":"science-class-1","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Young Scientist!"},{"type":"text","markdown":"Scientists ask questions and look closely at the world. Today is a **check-in**, not a test. Have a go at everything and tell a grown-up what you notice."},{"type":"image","emoji":"🔬","alt":"Let''s explore!","caption":"Let''s explore!"},{"type":"heading","text":"Stop 1: Living things"},{"type":"text","markdown":"Living things **grow**, **need food and water**, **move**, **have babies** and **sense** the world. Animals, plants and people are living. Rocks, toys and water are not living."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which one is living?","options":[{"id":"a","text":"A rock"},{"id":"b","text":"A tree"},{"id":"c","text":"A toy car"}],"answer":["b"]}},{"type":"heading","text":"Stop 2: Animals"},{"type":"text","markdown":"Animals can be sorted into groups. **Mammals** have fur or hair and feed their babies milk. **Birds** have feathers and wings. **Fish** live in water and have gills. **Insects** have six legs."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which animal is a bird?","options":[{"id":"a","text":"Penguin"},{"id":"b","text":"Dolphin"},{"id":"c","text":"Ant"}],"answer":["a"]}},{"type":"heading","text":"Stop 3: Plants"},{"type":"text","markdown":"Plants have **roots** that drink water, a **stem** that holds them up, **leaves** that catch sunlight and often **flowers** that make seeds. Plants need sunlight, water and air to grow."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which part of a plant drinks water from the soil?","options":[{"id":"a","text":"Leaves"},{"id":"b","text":"Flower"},{"id":"c","text":"Roots"}],"answer":["c"]}},{"type":"activity","title":"Seed hunt","materials":["a fruit such as an apple or orange","a plate"],"instructions":["Ask a grown-up to cut the fruit open.","Find the seeds. How many can you count?","Think: what might each seed grow into?"]},{"type":"explainer","title":"How a seed grows","scenes":[{"caption":"A tiny seed sits in the soil.","items":[{"emoji":"🟫","x":30,"y":88,"size":3},{"emoji":"🟫","x":50,"y":88,"size":3},{"emoji":"🟫","x":70,"y":88,"size":3},{"emoji":"🌰","x":50,"y":76,"id":"plant"}]},{"caption":"Rain and sunshine give it water and light.","items":[{"emoji":"🟫","x":30,"y":88,"size":3},{"emoji":"🟫","x":50,"y":88,"size":3},{"emoji":"🟫","x":70,"y":88,"size":3},{"emoji":"🌰","x":50,"y":76,"id":"plant"},{"emoji":"☀️","x":82,"y":15,"size":3,"anim":"spin"},{"emoji":"💧","x":50,"y":25,"anim":"bounce","label":"water"}]},{"caption":"The roots grow down and a little shoot pushes up.","items":[{"emoji":"🟫","x":30,"y":88,"size":3},{"emoji":"🟫","x":50,"y":88,"size":3},{"emoji":"🟫","x":70,"y":88,"size":3},{"emoji":"🌱","x":50,"y":66,"id":"plant","size":3,"anim":"grow"}]},{"caption":"At last it grows into a big flower!","items":[{"emoji":"🟫","x":30,"y":88,"size":3},{"emoji":"🟫","x":50,"y":88,"size":3},{"emoji":"🟫","x":70,"y":88,"size":3},{"emoji":"🌻","x":50,"y":50,"id":"plant","size":3,"anim":"float"}]}]},{"type":"heading","text":"Stop 4: Materials"},{"type":"text","markdown":"Things are made from **materials**. Glass is see-through and breakable. Metal is hard and shiny. Wood is strong. Rubber stretches. We pick materials that suit the job: a raincoat is **waterproof**."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which material is best for a window?","options":[{"id":"a","text":"Wood"},{"id":"b","text":"Glass"},{"id":"c","text":"Wool"}],"answer":["b"]}},{"type":"heading","text":"Stop 5: Weather and forces"},{"type":"text","markdown":"Weather can be sunny, rainy, windy, cloudy or snowy. A **force** is a push or a pull. We push a door open and pull a wagon."},{"type":"check","question":{"type":"multiple_choice","prompt":"Kicking a ball is a...","options":[{"id":"a","text":"Push"},{"id":"b","text":"Pull"}],"answer":["a"]}},{"type":"reveal","prompt":"What do you think happens to a puddle on a sunny day?","answer_markdown":"The Sun warms the water and it slowly turns into an invisible gas in the air. This is called evaporation."},{"type":"brain_game","game":"memory_match","title":"Find the living things","goal":"Match the pairs of animals and plants.","emojis":["🐶","🐟","🐦","🐛","🌻","🌳"]},{"type":"summary","points":["Living things grow, need food and water, and have babies.","Plants have roots, stems, leaves and flowers.","Different materials suit different jobs.","A force is a push or a pull."]},{"type":"callout","style":"tip","markdown":"Ready? Start the quiz. There are 12 questions and about 15 minutes. If you are not sure, take your best guess!"},{"type":"glossary","terms":[{"term":"check-in","meaning":"A friendly game that shows us what you know. It is not a test."},{"term":"mammal","meaning":"An animal with fur or hair that feeds its babies milk, like a dog or a cow."},{"term":"insect","meaning":"A small animal with 6 legs, like an ant or a bee."},{"term":"roots","meaning":"The part of a plant under the ground that drinks water."},{"term":"stem","meaning":"The part of a plant that holds it up and carries water."},{"term":"force","meaning":"A push or a pull."},{"term":"waterproof","meaning":"Water cannot get through it."},{"term":"materials","meaning":"What things are made of, like wood, metal or plastic."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"type":"multiple_choice","prompt":"Which of these is NOT living?","ref":"q1","skill_tag":"living.classify","options":[{"id":"a","text":"Cat"},{"id":"b","text":"Flower"},{"id":"c","text":"Pebble"},{"id":"d","text":"Bird"}],"answer":["c"]},{"type":"multi_select","prompt":"What do animals need to stay alive? Pick all that apply.","ref":"q2","skill_tag":"living.needs","points":2,"options":[{"id":"a","text":"Water"},{"id":"b","text":"Food"},{"id":"c","text":"Sweets only"},{"id":"d","text":"Air"}],"answer":["a","b","d"]},{"type":"multiple_choice","prompt":"Which animal is a mammal?","ref":"q3","skill_tag":"animals.groups","options":[{"id":"a","text":"Eagle"},{"id":"b","text":"Cow"},{"id":"c","text":"Frog"},{"id":"d","text":"Snake"}],"answer":["b"]},{"type":"true_false","prompt":"A spider is an insect.","hint":"Insects have six legs.","explanation":"Spiders have eight legs, so they are not insects.","ref":"q4","skill_tag":"animals.groups","answer":[false]},{"type":"multiple_choice","prompt":"Which part of a plant catches sunlight?","ref":"q5","skill_tag":"plants.parts","options":[{"id":"a","text":"Roots"},{"id":"b","text":"Leaves"},{"id":"c","text":"Seeds"}],"answer":["b"]},{"type":"multiple_choice","prompt":"Which of these does a plant need to grow?","ref":"q6","skill_tag":"plants.needs","options":[{"id":"a","text":"Sunlight and water"},{"id":"b","text":"Only chocolate"},{"id":"c","text":"Only darkness"}],"answer":["a"]},{"type":"multiple_choice","prompt":"Which part of your body do you use to smell?","ref":"q7","skill_tag":"body.senses","options":[{"id":"a","text":"Ears"},{"id":"b","text":"Nose"},{"id":"c","text":"Eyes"},{"id":"d","text":"Hands"}],"answer":["b"]},{"type":"match","prompt":"Match the thing to the material it is made from.","ref":"q8","skill_tag":"materials.uses","points":2,"left":[{"id":"l1","text":"Window"},{"id":"l2","text":"Wheels on a bike"},{"id":"l3","text":"Cooking pot"}],"right":[{"id":"r1","text":"Glass"},{"id":"r2","text":"Rubber"},{"id":"r3","text":"Metal"}],"answer":{"l1":"r1","l2":"r2","l3":"r3"}},{"type":"multiple_choice","prompt":"Which word describes a material that water cannot go through?","ref":"q9","skill_tag":"materials.properties","options":[{"id":"a","text":"Waterproof"},{"id":"b","text":"Stretchy"},{"id":"c","text":"Shiny"}],"answer":["a"]},{"type":"multiple_choice","prompt":"Which season is usually the coldest?","ref":"q10","skill_tag":"weather","options":[{"id":"a","text":"Summer"},{"id":"b","text":"Winter"},{"id":"c","text":"Spring"}],"answer":["b"]},{"type":"multiple_choice","prompt":"What gives us light and warmth in the day?","ref":"q11","skill_tag":"earth.day_night","options":[{"id":"a","text":"The Moon"},{"id":"b","text":"The Sun"},{"id":"c","text":"A cloud"}],"answer":["b"]},{"type":"multiple_choice","prompt":"Which of these is a pull?","ref":"q12","skill_tag":"forces","options":[{"id":"a","text":"Kicking a ball"},{"id":"b","text":"Pushing a swing"},{"id":"c","text":"Pulling a wagon"}],"answer":["c"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT 'a662a643-2f14-5a03-af38-0dde7b803579', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 9, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
