INSERT OR IGNORE INTO quizzes (id, kind, lesson_id, version, is_current, pass_percent, shuffle_questions, shuffle_options, max_attempts) VALUES ('19d30050-1e27-5a94-a411-07139629c37b', 'lesson', 'a662a643-2f14-5a03-af38-0dde7b803579', 1, 1, 1, 0, 1, NULL);
INSERT OR IGNORE INTO questions (id, quiz_id, ref, position, type, prompt, media_json, options_json, answer_json, hint, explanation, points, skill_tag) SELECT '19d30050-1e27-5a94-a411-07139629c37b' || ':' || json_extract(e.value,'$.ref'), '19d30050-1e27-5a94-a411-07139629c37b', json_extract(e.value,'$.ref'), e.key + 1, json_extract(e.value,'$.type'), json_extract(e.value,'$.prompt'), CASE WHEN json_extract(e.value,'$.emoji') IS NOT NULL THEN json_object('emoji', json_extract(e.value,'$.emoji')) END, CASE json_extract(e.value,'$.type') WHEN 'multiple_choice' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'multi_select' THEN json_object('options', json_extract(e.value,'$.options')) WHEN 'order' THEN json_object('items', json_extract(e.value,'$.items')) WHEN 'match' THEN json_object('left', json_extract(e.value,'$.left'), 'right', json_extract(e.value,'$.right')) ELSE 'null' END, json_extract(e.value,'$.answer'), json_extract(e.value,'$.hint'), json_extract(e.value,'$.explanation'), COALESCE(json_extract(e.value,'$.points'), 1), json_extract(e.value,'$.skill_tag') FROM lessons l, json_each(l.source_json, '$.quiz.questions') e WHERE l.id = 'a662a643-2f14-5a03-af38-0dde7b803579';
INSERT OR IGNORE INTO courses (id, slug, title, description, subject_id, age_band, status) VALUES ('90dc3e3c-b106-51e4-af87-bad3e017e698', 'science-class-4', 'Science (Class 4)', 'Science for Class 4', 'science', '9-10', 'published');
INSERT OR IGNORE INTO course_assignments (id, course_id, class_id, due_date) VALUES ('462c3e47-3dac-529e-a9ba-ff314b49f487', '90dc3e3c-b106-51e4-af87-bad3e017e698', 'bd51b0dc-00c1-5f33-a405-55d083fe30d1', '2026-11-08');
WITH src(j) AS (VALUES ('{"schema_version":"1.0","lesson":{"slug":"diag-science-class-4","subject":"science","title":"Science Check-In: Where Am I?","summary":"Check what you know about states of matter, food chains, forces, light and the body so we can plan your science year.","age_band":"9-10","difficulty":2,"estimated_minutes":60,"unit":"Week 1: Where am I?","learning_objectives":["Show what I know about living things, food chains and the body","Show what I know about states of matter and the water cycle","Show what I know about forces, light and electricity"],"tags":["diagnostic","week-1"],"curriculum":{"course":"science-class-4","semester":1,"week":1}},"blocks":[{"type":"heading","text":"Welcome, Scientist!"},{"type":"text","markdown":"This is a **check-in**, not a test. Scientists are curious and not afraid to guess. Show us what you know and where you are curious to learn more."},{"type":"image","emoji":"🧪","alt":"Science time!","caption":"Science time!"},{"type":"heading","text":"Stop 1: Solids, liquids and gases"},{"type":"text","markdown":"Matter comes in three main states. A **solid** keeps its shape. A **liquid** flows and takes the shape of its container. A **gas** spreads out to fill all the space. Heating can **melt** a solid or **boil** a liquid; cooling can **freeze** it or make a gas **condense**."},{"type":"check","question":{"type":"multiple_choice","prompt":"What do we call ice turning into water?","options":[{"id":"a","text":"Freezing"},{"id":"b","text":"Melting"},{"id":"c","text":"Evaporating"}],"answer":["b"]}},{"type":"heading","text":"Stop 2: The water cycle"},{"type":"text","markdown":"Water **evaporates** from seas and puddles, rises as vapour, **condenses** into clouds and falls as **rain**. Rivers carry it back to the sea."},{"type":"check","question":{"type":"multiple_choice","prompt":"What happens when water vapour cools in the sky?","options":[{"id":"a","text":"It condenses into clouds"},{"id":"b","text":"It turns into rock"},{"id":"c","text":"It disappears forever"}],"answer":["a"]}},{"type":"explainer","title":"The water cycle","scenes":[{"caption":"The Sun warms the sea.","items":[{"emoji":"☀️","x":85,"y":14,"size":3,"anim":"spin"},{"emoji":"🌊","x":50,"y":88,"size":3},{"emoji":"💧","x":30,"y":78,"id":"drop","label":"water"}]},{"caption":"The warm water evaporates and rises as invisible vapour.","items":[{"emoji":"☀️","x":85,"y":14,"size":3,"anim":"spin"},{"emoji":"🌊","x":50,"y":88,"size":3},{"emoji":"💧","x":30,"y":40,"id":"drop","label":"evaporates","anim":"float"}]},{"caption":"High up it cools and condenses into a cloud.","items":[{"emoji":"☀️","x":85,"y":14,"size":3,"anim":"spin"},{"emoji":"🌊","x":50,"y":88,"size":3},{"emoji":"☁️","x":30,"y":25,"id":"cloud","size":3,"label":"condenses","anim":"grow"}]},{"caption":"The cloud gets heavy and the water falls as rain. Then it starts all over again!","items":[{"emoji":"☀️","x":85,"y":14,"size":3,"anim":"spin"},{"emoji":"🌊","x":50,"y":88,"size":3},{"emoji":"🌧️","x":30,"y":25,"id":"cloud","size":3},{"emoji":"💧","x":30,"y":78,"id":"drop","label":"rain","anim":"bounce"}]}]},{"type":"heading","text":"Stop 3: Food chains"},{"type":"text","markdown":"Every food chain starts with a **producer**, a plant that makes its own food using sunlight. Animals that eat plants are **herbivores**; animals that eat other animals are **carnivores**. Grass, then rabbit, then fox is a food chain."},{"type":"check","question":{"type":"multiple_choice","prompt":"In the chain grass, rabbit, fox, which one is the producer?","options":[{"id":"a","text":"Grass"},{"id":"b","text":"Rabbit"},{"id":"c","text":"Fox"}],"answer":["a"]}},{"type":"activity","title":"My food chain","materials":["paper","coloured pencils"],"instructions":["Draw a food chain with at least 4 living things.","Label the producer, the herbivore and the carnivore.","Add arrows that point to what gets the energy."]},{"type":"heading","text":"Stop 4: Forces and magnets"},{"type":"text","markdown":"Forces can speed things up, slow them down or change their shape. **Friction** slows things that rub together. **Gravity** pulls things toward the Earth. A **magnet** pulls some metals, like iron, but not wood or plastic."},{"type":"check","question":{"type":"multiple_choice","prompt":"Which force pulls objects down to the ground?","options":[{"id":"a","text":"Gravity"},{"id":"b","text":"Friction"},{"id":"c","text":"Magnetism"}],"answer":["a"]}},{"type":"heading","text":"Stop 5: Light, sound and circuits"},{"type":"text","markdown":"Light travels in straight lines, so objects block it and make **shadows**. Sound is made by **vibrations**. An electric **circuit** needs a complete loop with a battery, wires and a bulb for the bulb to light."},{"type":"check","question":{"type":"true_false","prompt":"A bulb will light if the circuit has a gap in it.","answer":[false]}},{"type":"reveal","prompt":"Why is your shadow longer in the evening than at noon?","answer_markdown":"The Sun is low in the sky in the evening, so light hits you at a shallow angle and the shadow stretches out."},{"type":"brain_game","game":"remember_order","title":"Water cycle memory","goal":"Watch the order, then copy it.","emojis":["🌞","💧","☁️","🌧️"]},{"type":"summary","points":["Solids, liquids and gases behave differently and can change state.","Water moves round in a cycle.","Food chains start with plants that make their own food.","Forces push or pull and gravity pulls things down.","A circuit must be a complete loop."]},{"type":"callout","style":"tip","markdown":"Ready? Start the quiz. It has 12 questions and about 15 minutes. A guess is better than a blank."},{"type":"glossary","terms":[{"term":"evaporate","meaning":"Liquid water turns into an invisible gas called water vapour."},{"term":"condense","meaning":"A gas cools down and turns back into tiny drops of liquid."},{"term":"producer","meaning":"A plant that makes its own food using sunlight."},{"term":"carnivore","meaning":"An animal that eats other animals."},{"term":"herbivore","meaning":"An animal that eats only plants."},{"term":"friction","meaning":"A force that slows things down when they rub together."},{"term":"gravity","meaning":"The force that pulls things toward the ground."},{"term":"circuit","meaning":"A complete loop that electricity can flow around."}]}],"quiz":{"pass_percent":1,"shuffle_questions":false,"shuffle_options":true,"max_attempts":null,"questions":[{"type":"multiple_choice","prompt":"Which of these is a gas?","ref":"q1","skill_tag":"matter.states","options":[{"id":"a","text":"Milk"},{"id":"b","text":"Steam"},{"id":"c","text":"Ice"},{"id":"d","text":"Sand"}],"answer":["b"]},{"type":"multiple_choice","prompt":"What do we call water turning into water vapour?","ref":"q2","skill_tag":"matter.changes","options":[{"id":"a","text":"Condensing"},{"id":"b","text":"Evaporating"},{"id":"c","text":"Freezing"}],"answer":["b"]},{"type":"multiple_choice","prompt":"Which of these is part of the water cycle?","ref":"q3","skill_tag":"water.cycle","options":[{"id":"a","text":"Rain falling"},{"id":"b","text":"Rocks melting"},{"id":"c","text":"Plants singing"}],"answer":["a"]},{"type":"multiple_choice","prompt":"In a food chain, what do the arrows show?","ref":"q4","skill_tag":"food.chains","points":2,"options":[{"id":"a","text":"Which animal is biggest"},{"id":"b","text":"The flow of energy (who eats whom)"},{"id":"c","text":"The way animals walk"}],"answer":["b"]},{"type":"multi_select","prompt":"Which of these are herbivores? Pick all that apply.","ref":"q5","skill_tag":"food.chains","points":2,"options":[{"id":"a","text":"Rabbit"},{"id":"b","text":"Lion"},{"id":"c","text":"Cow"},{"id":"d","text":"Eagle"}],"answer":["a","c"]},{"type":"multiple_choice","prompt":"What do plants use sunlight for?","ref":"q6","skill_tag":"plants.photosynthesis","options":[{"id":"a","text":"To make their own food"},{"id":"b","text":"To keep warm at night"},{"id":"c","text":"To make noise"}],"answer":["a"]},{"type":"multiple_choice","prompt":"What is the main job of the skeleton?","ref":"q7","skill_tag":"body.skeleton","options":[{"id":"a","text":"Support the body and protect organs"},{"id":"b","text":"Digest food"},{"id":"c","text":"Make sounds"}],"answer":["a"]},{"type":"multiple_choice","prompt":"Where does most of our food get digested?","ref":"q8","skill_tag":"body.digestion","options":[{"id":"a","text":"Lungs"},{"id":"b","text":"Stomach and intestines"},{"id":"c","text":"Brain"}],"answer":["b"]},{"type":"multiple_choice","prompt":"Which object would a magnet pick up?","ref":"q9","skill_tag":"forces.magnets","options":[{"id":"a","text":"Iron nail"},{"id":"b","text":"Wooden spoon"},{"id":"c","text":"Plastic cup"},{"id":"d","text":"Rubber band"}],"answer":["a"]},{"type":"true_false","prompt":"Friction makes things slide more easily.","explanation":"Friction slows things down when they rub together.","ref":"q10","skill_tag":"forces.friction","answer":[false]},{"type":"multiple_choice","prompt":"What makes a shadow?","ref":"q11","skill_tag":"light.shadows","options":[{"id":"a","text":"An object blocking light"},{"id":"b","text":"Light bending round corners"},{"id":"c","text":"Sound waves"}],"answer":["a"]},{"type":"multiple_choice","prompt":"What does a circuit need so that a bulb lights up?","ref":"q12","skill_tag":"electricity.circuit","points":2,"options":[{"id":"a","text":"A complete loop with a battery"},{"id":"b","text":"Only a bulb"},{"id":"c","text":"Only wires"}],"answer":["a"]}]}}')) INSERT OR IGNORE INTO lessons (id, slug, subject_id, title, summary, age_band, difficulty, estimated_minutes, unit, sort_order, status, current_version, content_json, source_json) SELECT '44589116-a64d-528e-a6f3-e3e4ee02c3bc', json_extract(j,'$.lesson.slug'), json_extract(j,'$.lesson.subject'), json_extract(j,'$.lesson.title'), json_extract(j,'$.lesson.summary'), json_extract(j,'$.lesson.age_band'), json_extract(j,'$.lesson.difficulty'), json_extract(j,'$.lesson.estimated_minutes'), json_extract(j,'$.lesson.unit'), 10, 'published', 1, json_extract(j,'$.blocks'), j FROM src;
